const b = $json.body || {};
const li = b.line_items?.[0] || {};
const o = {
  OrderID: b.id || b.order_id || ('ORD-'+Date.now()),
  Date: new Date().toISOString().slice(0,10),
  Customer: b.customer ? ((b.customer.first_name||'')+' '+(b.customer.last_name||'')).trim() : (b.customer_name || b.customer || 'Customer'),
  Phone: b.phone || b.customer?.phone || b.shipping_address?.phone || '',
  Item: li.title || b.item || '',
  Qty: li.quantity || b.qty || 1,
  Amount: b.total_price || b.amount || '',
  Payment: (b.financial_status || b.payment || '').toString().toLowerCase().includes('cod') ? 'COD' : (b.financial_status || b.payment || 'Prepaid'),
  ShipStatus: 'New', AWB: ''
};
return [{ json: o }];

const o = $('Normalise order').item.json;
const row = items.map(i=>i.json).find(r => (r.Item||'').toLowerCase() === (o.Item||'').toLowerCase());
if (!row) return [];
return [{ json: { row_number: row.row_number, Qty: Math.max(0, Number(row.Qty||0) - Number(o.Qty||1)) } }];

